import{c as a,S as i,j as r,m as l}from"./chunks/framework.8aa1YH_s.js";const g=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 18: Cümle Bilgisi (Sentaks) - Cümlenin Ögeleri","description":"","frontmatter":{},"headers":[],"relativePath":"18 Cümle Bilgisi (Sentaks) - Cümlenin Ögeleri.md","filePath":"18 Cümle Bilgisi (Sentaks) - Cümlenin Ögeleri.md"}'),n={name:"18 Cümle Bilgisi (Sentaks) - Cümlenin Ögeleri.md"};function m(t,e,s,o,u,d){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="turk-dil-bilgisi-serisi-18-cumle-bilgisi-sentaks-cumlenin-ogeleri" tabindex="-1">Türk Dil Bilgisi Serisi - 18: Cümle Bilgisi (Sentaks) - Cümlenin Ögeleri <a class="header-anchor" href="#turk-dil-bilgisi-serisi-18-cumle-bilgisi-sentaks-cumlenin-ogeleri" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 18: Cümle Bilgisi (Sentaks) - Cümlenin Ögeleri”">​</a></h1><p>Dil bilgisi yolculuğumuzun bu bölümünde, seslerden köklere, eklerden kelime türlerine kadar öğrendiğimiz tüm parçaları birleştirerek en üst yapıya ulaşıyoruz: <strong>Cümle Bilgisi (Sentaks)</strong>.</p><p>Prof. Dr. Muharrem Ergin’e göre cümle; bir fikri, bir duyguyu, bir hareketi veya bir olayı bir hüküm halinde, tam bir bütün olarak ifade eden kelime veya kelimeler topluluğudur. Cümleyi ayakta tutan ve ona anlam kazandıran parçalara ise <strong>Cümlenin Ögeleri</strong> denir.</p><p>Muharrem Ergin sistematiğinde cümlenin ögeleri, önem sırasına göre <strong>Asli Ögeler</strong> ve <strong>Yardımcı Ögeler</strong> olmak üzere iki ana grupta incelenir.</p><hr><h2 id="_1-asli-ogeler-cumlenin-temel-direkleri" tabindex="-1">1. Asli Ögeler (Cümlenin Temel Direkleri) <a class="header-anchor" href="#_1-asli-ogeler-cumlenin-temel-direkleri" aria-label="Permalink to “1. Asli Ögeler (Cümlenin Temel Direkleri)”">​</a></h2><p>Bir cümlenin var olabilmesi, bir hüküm bildirebilmesi için bu iki ögenin bulunması (veya zihnen var olması) şarttır.</p><h3 id="a-yuklem-cumlenin-kalbi" tabindex="-1">A) Yüklem (Cümlenin Kalbi) <a class="header-anchor" href="#a-yuklem-cumlenin-kalbi" aria-label="Permalink to “A) Yüklem (Cümlenin Kalbi)”">​</a></h3><p>Cümledeki hükmü, işi, oluşu veya hareketi zaman ve şahsa bağlayarak üzerine alan en temel unsurdur. Yüklem olmadan cümle kurulamaz. Türkçede yüklem genellikle <strong>cümlenin sonunda</strong> yer alır.</p><ul><li><strong>Fiil Yüklemi:</strong> <em>Mehmet yeni projeyi dün <strong>bitirdi</strong>.</em></li><li><strong>İsim Yüklemi:</strong> <em>En sevdiği futbol kulübü <strong>Beşiktaş&#39;tır</strong>.</em></li></ul><h3 id="b-ozne-isi-yapan-aktor" tabindex="-1">B) Özne (İşi Yapan Aktör) <a class="header-anchor" href="#b-ozne-isi-yapan-aktor" aria-label="Permalink to “B) Özne (İşi Yapan Aktör)”">​</a></h3><p>Yüklemin bildirdiği işi, hareketi icra eden veya yüklemdeki duruma sahip olan varlıktır. Yükleme sorulan <strong>&quot;Kim?&quot;</strong> (insanlar için) veya <strong>&quot;Ne?&quot;</strong> (cansız varlıklar için) sorularıyla bulunur.</p><ul><li><strong>Gerçek Özne:</strong> <em><strong>Yazılımcı</strong>, hatayı saniyeler içinde düzeltti.</em> (İşi yapan belli).</li><li><strong>Gizli Özne:</strong> <em>Dün akşam maçı izledik.</em> (Yüklemdeki &quot;-k&quot; ekinden öznenin <strong>&quot;Biz&quot;</strong> olduğu anlaşılıyor).</li><li><strong>Sözde Özne (Edilgen cümlelerde):</strong> <em><strong>Sokaklar</strong> sabaha karşı temizlendi.</em> (Temizleyen belli değil, etkilenen sokaklar özneleşmiştir).</li></ul><hr><h2 id="_2-yardımcı-ogeler-cumleyi-zenginlestiren-unsurlar" tabindex="-1">2. Yardımcı Ögeler (Cümleyi Zenginleştiren Unsurlar) <a class="header-anchor" href="#_2-yardımcı-ogeler-cumleyi-zenginlestiren-unsurlar" aria-label="Permalink to “2. Yardımcı Ögeler (Cümleyi Zenginleştiren Unsurlar)”">​</a></h2><p>Temel ögelerin kurduğu hükmü yer, zaman, miktar, yön veya nesne bakımından tamamlayan, detaylandıran ögelerdir.</p><h3 id="a-nesne-duz-tumlec" tabindex="-1">A) Nesne (Düz Tümleç) <a class="header-anchor" href="#a-nesne-duz-tumlec" aria-label="Permalink to “A) Nesne (Düz Tümleç)”">​</a></h3><p>Cümlede öznenin yaptığı işten doğrudan doğruya etkilenen varlıktır. Sadece <strong>geçişli fiillerin</strong> yüklem olduğu cümlelerde bulunur. İki çeşittir:</p><ol><li><strong>Belirtili Nesne:</strong> İsmin belirtme hal ekini (<code>-ı, -i, -u, -ü</code>) alır. Yükleme sorulan <strong>&quot;Neyi?&quot;</strong> veya <strong>&quot;Kimi?&quot;</strong> sorularının cevabıdır. <ul><li><em>Örnek:</em> <em>Ahmet <strong>kitabı</strong> masaya bıraktı.</em> (<em>Neyi bıraktı? -&gt; Kitabı</em>)</li></ul></li><li><strong>Belirtisiz Nesne:</strong> Hal eki almaz, yalın durumdadır. Özne bulunduktan sonra yükleme sorulan ilk <strong>&quot;Ne?&quot;</strong> sorusunun cevabıdır. <ul><li><em>Örnek:</em> <em>Annem mutfakta <strong>börek</strong> yapıyor.</em> (<em>Ne yapıyor? -&gt; Börek</em>)</li></ul></li></ol><h3 id="b-yer-tamlayıcısı-dolaylı-tumlec" tabindex="-1">B) Yer Tamlayıcısı (Dolaylı Tümleç) <a class="header-anchor" href="#b-yer-tamlayıcısı-dolaylı-tumlec" aria-label="Permalink to “B) Yer Tamlayıcısı (Dolaylı Tümleç)”">​</a></h3><p>Yüklemin bildirdiği hareketi yer, mekân ve doğrultu bakımından tamamlayan ögedir. Yer tamlayıcısı olan kelimeler mutlaka ismin <strong><code>-e</code> (Yönelme)</strong>, <strong><code>-de</code> (Bulunma)</strong> veya <strong><code>-den</code> (Ayrılma)</strong> hal eklerinden birini taşımak zorundadır.</p><ul><li><strong>Soruları:</strong> <em>Nereye? Nerede? Nereden? / Kime? Kimde? Kimden?</em></li><li><em>Örnekler:</em><ul><li><em>Çocuk koşarak <strong>eve</strong> girdi.</em> (<em>Nereye girdi? -&gt; Eve</em>)</li><li><em>Anahtarlarımı <strong>masada</strong> unutmuşum.</em> (<em>Nerede unutmuşum? -&gt; Masada</em>)</li><li><em>Dün akşam <strong>Brüksel&#39;den</strong> döndü.</em> (<em>Nereden döndü? -&gt; Brüksel&#39;den</em>)</li></ul></li></ul><h3 id="c-zarf-tamlayıcısı-zarf-tumleci" tabindex="-1">C) Zarf Tamlayıcısı (Zarf Tümleci) <a class="header-anchor" href="#c-zarf-tamlayıcısı-zarf-tumleci" aria-label="Permalink to “C) Zarf Tamlayıcısı (Zarf Tümleci)”">​</a></h3><p>Yüklemin anlamını zaman, tarz (nasıl yapıldığı), miktar, sebep, vasıta veya şart yönünden sınırlayan ve tamamlayan ögedir.</p><ul><li><strong>Soruları:</strong> <em>Nasıl? Ne zaman? Ne kadar? Niçin? Neden?</em></li><li><em>Örnekler:</em><ul><li><em>Takım bu akşam <strong>çok iyi</strong> oynadı.</em> (<em>Nasıl oynadı? -&gt; Çok iyi</em>)</li><li><em>Yeni güncelleme <strong>haftaya</strong> yayınlanacak.</em> (<em>Ne zaman yayınlanacak? -&gt; Haftaya</em>)</li><li><em>Sıcaklardan dolayı <strong>hiç</strong> uyuyamadım.</em> (<em>Ne kadar uyuyamadım? -&gt; Hiç</em>)</li></ul></li></ul><hr><h2 id="ozet-cumle-cozumlerken-muharrem-ergin-in-altın-sıralaması" tabindex="-1">Özet: Cümle Çözümlerken Muharrem Ergin&#39;in Altın Sıralaması <a class="header-anchor" href="#ozet-cumle-cozumlerken-muharrem-ergin-in-altın-sıralaması" aria-label="Permalink to “Özet: Cümle Çözümlerken Muharrem Ergin&#39;in Altın Sıralaması”">​</a></h2><p>Bir cümlenin ögelerini bulurken hata yapmamak için her zaman şu hiyerarşik sıra takip edilmelidir:</p><p>$$\\text{1. Yüklem} \\rightarrow \\text{2. Özne} \\rightarrow \\text{3. Nesne} \\rightarrow \\text{4. Tümleçler (Yer ve Zarf)}$$</p><blockquote><p><strong>⚠️ En Büyük Tuzak:</strong> Önce özneyi bulmadan nesneyi aramaya kalkarsanız, belirtisiz nesne ile özneyi birbirine karıştırırsınız. Önce her zaman &quot;işi yapan&quot; (özne), sonra &quot;işten etkilenen&quot; (nesne) bulunmalıdır!</p></blockquote>',30)])])}const y=a(n,[["render",m]]);export{g as __pageData,y as default};
